'use client';

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import {
  Search,
  LayoutDashboard,
  ShoppingBag,
  CreditCard,
  Wallet,
  Users,
  Settings,
  HelpCircle,
  Plus,
  ArrowRight,
  Command,
  X,
  Sparkles,
  Zap
} from 'lucide-react';
import { useStore } from '@/store/useStore';

export default function CommandPalette() {
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [selectedIndex, setSelectedIndex] = useState(0);
  const router = useRouter();
  const { role } = useStore();

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Toggle palette on Cmd+K or Ctrl+K
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        setIsOpen((prev) => !prev);
      }

      // Close on Esc
      if (e.key === 'Escape') {
        setIsOpen(false);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  if (!isOpen) return null;

  const getDashboardPath = () => {
    if (['admin', 'superadmin'].includes(role)) return '/admin';
    if (['vendor', 'seller'].includes(role)) return '/seller';
    if (role === 'reseller') return '/reseller';
    if (role === 'deliveryman') return '/delivery';
    return '/account';
  };

  const actions = [
    {
      id: 'dash',
      title: 'Go to Dashboard Overview',
      category: 'Navigation',
      icon: LayoutDashboard,
      shortcut: 'G D',
      perform: () => router.push(getDashboardPath())
    },
    {
      id: 'products',
      title: 'View Catalog & Inventory',
      category: 'Navigation',
      icon: ShoppingBag,
      shortcut: 'G P',
      perform: () => router.push('/seller')
    },
    {
      id: 'orders',
      title: 'View Active Orders & Processing',
      category: 'Navigation',
      icon: CreditCard,
      shortcut: 'G O',
      perform: () => router.push(getDashboardPath())
    },
    {
      id: 'wallet',
      title: 'Store Wallet & Payout Ledger',
      category: 'Navigation',
      icon: Wallet,
      shortcut: 'G W',
      perform: () => router.push('/seller')
    },
    {
      id: 'staff',
      title: 'Manage Staff Members & Roles',
      category: 'Management',
      icon: Users,
      perform: () => router.push('/seller/staff')
    },
    {
      id: 'add-product',
      title: 'Upload New Product SKU',
      category: 'Quick Actions',
      icon: Plus,
      perform: () => {
        router.push('/seller');
      }
    },
    {
      id: 'ai-insights',
      title: 'Ask AI Copilot for Sales Forecast',
      category: 'AI Copilot',
      icon: Sparkles,
      perform: () => {
        router.push(getDashboardPath());
      }
    }
  ];

  const filteredActions = actions.filter((action) =>
    action.title.toLowerCase().includes(query.toLowerCase()) ||
    action.category.toLowerCase().includes(query.toLowerCase())
  );

  const handleSelect = (action: typeof actions[0]) => {
    action.perform();
    setIsOpen(false);
    setQuery('');
  };

  return (
    <div className="fixed inset-0 z-[9999] bg-slate-950/80 backdrop-blur-md flex items-start justify-center pt-20 px-4 animate-fade-in">
      <div className="w-full max-w-2xl bg-slate-900 border border-slate-800 rounded-2xl shadow-modal overflow-hidden animate-in-scale">
        {/* Header Search Box */}
        <div className="flex items-center gap-3 px-4 py-3.5 border-b border-slate-800 bg-slate-950/40">
          <Search className="w-5 h-5 text-amber-400 shrink-0" />
          <input
            type="text"
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              setSelectedIndex(0);
            }}
            placeholder="Type a command, search products, or jump to route... (Cmd + K)"
            className="w-full bg-transparent text-slate-100 placeholder-slate-500 text-sm focus:outline-none"
            autoFocus
          />
          <button
            onClick={() => setIsOpen(false)}
            className="p-1 text-slate-500 hover:text-slate-300 rounded-lg hover:bg-slate-800/50 transition"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Action Options List */}
        <div className="max-h-[360px] overflow-y-auto p-2 space-y-1">
          {filteredActions.length === 0 ? (
            <div className="py-8 text-center text-slate-500 text-xs font-medium">
              No command or navigation target found matching &quot;{query}&quot;
            </div>
          ) : (
            filteredActions.map((action, idx) => {
              const Icon = action.icon;
              const isSelected = idx === selectedIndex;
              return (
                <button
                  key={action.id}
                  onClick={() => handleSelect(action)}
                  onMouseEnter={() => setSelectedIndex(idx)}
                  className={`w-full flex items-center justify-between px-3.5 py-2.5 rounded-xl text-left transition-all ${
                    isSelected
                      ? 'bg-amber-500/10 text-amber-400 border border-amber-500/20'
                      : 'text-slate-300 hover:bg-slate-800/60'
                  }`}
                >
                  <div className="flex items-center gap-3">
                    <div
                      className={`p-2 rounded-lg ${
                        isSelected ? 'bg-amber-500/20 text-amber-400' : 'bg-slate-800 text-slate-400'
                      }`}
                    >
                      <Icon className="w-4 h-4" />
                    </div>
                    <div>
                      <p className="text-xs font-bold">{action.title}</p>
                      <p className="text-[10px] text-slate-500">{action.category}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    {action.shortcut && (
                      <span className="text-[10px] font-mono bg-slate-800 border border-slate-700 text-slate-400 px-2 py-0.5 rounded">
                        {action.shortcut}
                      </span>
                    )}
                    <ArrowRight className="w-3.5 h-3.5 opacity-60" />
                  </div>
                </button>
              );
            })
          )}
        </div>

        {/* Footer shortcuts helper */}
        <div className="flex items-center justify-between px-4 py-2.5 bg-slate-950/60 border-t border-slate-800 text-[10px] text-slate-500 font-medium">
          <div className="flex items-center gap-3">
            <span className="flex items-center gap-1">
              <kbd className="px-1.5 py-0.5 bg-slate-800 rounded border border-slate-700 font-mono text-slate-400">↑↓</kbd>{' '}
              Navigate
            </span>
            <span className="flex items-center gap-1">
              <kbd className="px-1.5 py-0.5 bg-slate-800 rounded border border-slate-700 font-mono text-slate-400">↵</kbd>{' '}
              Select
            </span>
            <span className="flex items-center gap-1">
              <kbd className="px-1.5 py-0.5 bg-slate-800 rounded border border-slate-700 font-mono text-slate-400">Esc</kbd>{' '}
              Close
            </span>
          </div>
          <div className="flex items-center gap-1 text-amber-400/80">
            <Zap className="w-3 h-3" />
            <span>Zibonbaba Enterprise Core</span>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import { Search, ChevronLeft, ChevronRight, Download, Trash2, Edit, CheckSquare, Square, Filter, ChevronDown, ArrowUpDown } from 'lucide-react';

export interface Column<T> {
  header: string;
  accessor: keyof T | ((row: T) => React.ReactNode);
  sortable?: boolean;
  sortKey?: string;
  width?: string;
}

interface EnterpriseDataTableProps<T extends { id: string | number }> {
  columns: Column<T>[];
  data: T[];
  searchPlaceholder?: string;
  title?: string;
  isLoading?: boolean;
  bulkActions?: {
    label: string;
    icon?: React.ComponentType<{ className?: string }>;
    variant?: 'danger' | 'primary' | 'secondary';
    onClick: (selectedRows: T[]) => void;
  }[];
  onRowClick?: (row: T) => void;
}

export default function EnterpriseDataTable<T extends { id: string | number }>({
  columns,
  data,
  searchPlaceholder = 'Search records...',
  title,
  isLoading = false,
  bulkActions,
  onRowClick
}: EnterpriseDataTableProps<T>) {
  const [search, setSearch] = useState('');
  const [selectedIds, setSelectedIds] = useState<Set<string | number>>(new Set());
  const [sortField, setSortField] = useState<string | null>(null);
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);

  // Search Filtering
  const filteredData = useMemo(() => {
    if (!search.trim()) return data;
    const q = search.toLowerCase();
    return data.filter((row) =>
      Object.values(row).some((val) =>
        String(val || '').toLowerCase().includes(q)
      )
    );
  }, [data, search]);

  // Sorting
  const sortedData = useMemo(() => {
    if (!sortField) return filteredData;
    return [...filteredData].sort((a: any, b: any) => {
      const valA = a[sortField];
      const valB = b[sortField];
      if (valA < valB) return sortDirection === 'asc' ? -1 : 1;
      if (valA > valB) return sortDirection === 'asc' ? 1 : -1;
      return 0;
    });
  }, [filteredData, sortField, sortDirection]);

  // Pagination
  const totalPages = Math.ceil(sortedData.length / pageSize) || 1;
  const paginatedData = useMemo(() => {
    const start = (page - 1) * pageSize;
    return sortedData.slice(start, start + pageSize);
  }, [sortedData, page, pageSize]);

  // Bulk Selection
  const allSelected = paginatedData.length > 0 && paginatedData.every((r) => selectedIds.has(r.id));

  const toggleSelectAll = () => {
    const next = new Set(selectedIds);
    if (allSelected) {
      paginatedData.forEach((r) => next.delete(r.id));
    } else {
      paginatedData.forEach((r) => next.add(r.id));
    }
    setSelectedIds(next);
  };

  const toggleSelectRow = (id: string | number) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const selectedRows = useMemo(() => {
    return data.filter((r) => selectedIds.has(r.id));
  }, [data, selectedIds]);

  const handleSort = (key?: string) => {
    if (!key) return;
    if (sortField === key) {
      setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(key);
      setSortDirection('asc');
    }
  };

  return (
    <div className="w-full bg-slate-900 border border-slate-800 rounded-2xl shadow-card overflow-hidden text-slate-200">
      {/* Header Toolbar */}
      <div className="p-4 border-b border-slate-800 flex flex-col md:flex-row md:items-center justify-between gap-4 bg-slate-950/40">
        <div className="flex items-center gap-3">
          {title && <h3 className="text-base font-bold text-slate-100">{title}</h3>}
          <span className="text-xs font-mono bg-slate-800 text-amber-400 px-2.5 py-1 rounded-lg border border-slate-700 font-semibold">
            {filteredData.length} records
          </span>
        </div>

        {/* Search input */}
        <div className="relative flex-grow max-w-md">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
          <input
            type="text"
            value={search}
            onChange={(e) => {
              setSearch(e.target.value);
              setPage(1);
            }}
            placeholder={searchPlaceholder}
            className="w-full bg-slate-950 border border-slate-800 text-slate-100 text-xs rounded-xl pl-9 pr-4 py-2 focus:outline-none focus:border-amber-500/50 transition"
          />
        </div>
      </div>

      {/* Main Table */}
      <div className="overflow-x-auto">
        <table className="w-full text-left text-xs border-collapse">
          <thead className="bg-slate-950/80 text-slate-400 font-semibold border-b border-slate-800 uppercase tracking-wider text-[10px]">
            <tr>
              <th className="p-3.5 w-10 text-center">
                <input
                  type="checkbox"
                  checked={allSelected}
                  onChange={toggleSelectAll}
                  className="rounded border-slate-700 bg-slate-950 text-amber-500 focus:ring-amber-500/30 cursor-pointer"
                />
              </th>
              {columns.map((col, i) => (
                <th
                  key={i}
                  className={`p-3.5 ${col.sortable ? 'cursor-pointer select-none hover:text-slate-200' : ''}`}
                  onClick={() => col.sortable && handleSort(col.sortKey || (typeof col.accessor === 'string' ? (col.accessor as string) : undefined))}
                  style={{ width: col.width }}
                >
                  <div className="flex items-center gap-1.5">
                    <span>{col.header}</span>
                    {col.sortable && <ArrowUpDown className="w-3 h-3 opacity-60" />}
                  </div>
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-800/60">
            {isLoading ? (
              Array.from({ length: 5 }).map((_, i) => (
                <tr key={i} className="animate-pulse">
                  <td className="p-3.5"><div className="w-4 h-4 bg-slate-800 rounded"></div></td>
                  {columns.map((_, colIdx) => (
                    <td key={colIdx} className="p-3.5">
                      <div className="h-3 bg-slate-800 rounded w-3/4"></div>
                    </td>
                  ))}
                </tr>
              ))
            ) : paginatedData.length === 0 ? (
              <tr>
                <td colSpan={columns.length + 1} className="p-10 text-center text-slate-500 font-medium">
                  No records match search parameters.
                </td>
              </tr>
            ) : (
              paginatedData.map((row) => {
                const isChecked = selectedIds.has(row.id);
                return (
                  <tr
                    key={row.id}
                    onClick={() => onRowClick && onRowClick(row)}
                    className={`transition-colors ${
                      isChecked ? 'bg-amber-500/5' : 'hover:bg-slate-800/40'
                    } ${onRowClick ? 'cursor-pointer' : ''}`}
                  >
                    <td className="p-3.5 text-center" onClick={(e) => e.stopPropagation()}>
                      <input
                        type="checkbox"
                        checked={isChecked}
                        onChange={() => toggleSelectRow(row.id)}
                        className="rounded border-slate-700 bg-slate-950 text-amber-500 focus:ring-amber-500/30 cursor-pointer"
                      />
                    </td>
                    {columns.map((col, cIdx) => (
                      <td key={cIdx} className="p-3.5 font-medium text-slate-200">
                        {typeof col.accessor === 'function' ? col.accessor(row) : (row[col.accessor] as any)}
                      </td>
                    ))}
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {/* Floating Bulk Action Bar */}
      {selectedIds.size > 0 && bulkActions && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-50 bg-slate-950 border border-amber-500/30 rounded-2xl px-6 py-3 shadow-modal flex items-center gap-4 text-xs animate-slide-up backdrop-blur-xl">
          <span className="font-bold text-slate-200">
            <span className="text-amber-400 font-mono font-black">{selectedIds.size}</span> item(s) selected
          </span>
          <div className="h-4 w-[1px] bg-slate-800"></div>
          <div className="flex items-center gap-2">
            {bulkActions.map((action, idx) => (
              <button
                key={idx}
                onClick={() => action.onClick(selectedRows)}
                className={`px-3 py-1.5 rounded-xl font-bold transition flex items-center gap-1.5 ${
                  action.variant === 'danger'
                    ? 'bg-rose-500/10 border border-rose-500/20 text-rose-400 hover:bg-rose-500/20'
                    : 'bg-amber-500 text-slate-950 hover:bg-amber-400'
                }`}
              >
                {action.label}
              </button>
            ))}
            <button
              onClick={() => setSelectedIds(new Set())}
              className="px-2.5 py-1.5 text-slate-400 hover:text-slate-200 text-xs font-semibold"
            >
              Clear
            </button>
          </div>
        </div>
      )}

      {/* Pagination Footer */}
      <div className="p-4 border-t border-slate-800 flex items-center justify-between text-xs text-slate-400 bg-slate-950/40">
        <div>
          Showing <span className="font-bold text-slate-200">{(page - 1) * pageSize + 1}</span> to{' '}
          <span className="font-bold text-slate-200">{Math.min(page * pageSize, sortedData.length)}</span> of{' '}
          <span className="font-bold text-slate-200">{sortedData.length}</span> entries
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={page === 1}
            className="p-1.5 rounded-lg border border-slate-800 bg-slate-900 disabled:opacity-40 hover:bg-slate-800 transition"
          >
            <ChevronLeft className="w-4 h-4" />
          </button>
          <span className="text-xs font-bold text-slate-200">
            Page {page} of {totalPages}
          </span>
          <button
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
            disabled={page === totalPages || totalPages === 0}
            className="p-1.5 rounded-lg border border-slate-800 bg-slate-900 disabled:opacity-40 hover:bg-slate-800 transition"
          >
            <ChevronRight className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { usePathname, useRouter } from 'next/navigation';
import Navbar from '@/components/navbar';
import Footer from '@/components/footer';
import { useIsMobile } from '@/hooks/useIsMobile';
import PWARegister from '@/components/pwa-register';
import MobileHeader from '@/components/mobile-header';
import MobileBottomNavigation from '@/components/mobile-bottom-navigation';
import CommandPalette from '@/components/command-palette';
import { useStore } from '@/store/useStore';
import { Bell, X } from 'lucide-react';
import { getDashboardForRole, isCustomerInterfaceRoute, shouldHideStorefrontHeader } from '@/utils/roleRoutes';

export default function LayoutClient({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const router = useRouter();
  const { isMobile, isMounted } = useIsMobile();
  const { isLoggedIn, role, initNotificationWebSocket } = useStore();
  const [toast, setToast] = useState<any | null>(null);

  const hideStorefront = shouldHideStorefrontHeader(pathname, role, isLoggedIn);

  // Strict Client-Side Role Isolation Guard
  useEffect(() => {
    if (isLoggedIn && typeof window !== 'undefined') {
      const storedUser = localStorage.getItem('zibonbaba_user');
      if (storedUser) {
        try {
          const u = JSON.parse(storedUser);
          const currentRole = u.role ? u.role.trim().toUpperCase() : 'CUSTOMER';
          if (currentRole !== 'CUSTOMER' && isCustomerInterfaceRoute(pathname)) {
            const targetDashboard = getDashboardForRole(currentRole);
            if (pathname !== targetDashboard) {
              router.replace(targetDashboard);
            }
          }
        } catch (_) {}
      }
    }
  }, [isLoggedIn, pathname, router]);

  // Subscribe to real-time WebSockets
  useEffect(() => {
    if (isLoggedIn) {
      const storedUser = localStorage.getItem('zibonbaba_user');
      if (storedUser) {
        try {
          const u = JSON.parse(storedUser);
          if (u.id) {
            const disconnect = initNotificationWebSocket(u.id);
            return () => disconnect();
          }
        } catch (_) {}
      }
    }
  }, [isLoggedIn, initNotificationWebSocket]);

  // Capture slide-up toasts
  useEffect(() => {
    const handleToast = (e: any) => {
      setToast(e.detail);
      const timer = setTimeout(() => {
        setToast(null);
      }, 5000);
      return () => clearTimeout(timer);
    };

    window.addEventListener('zibonbaba-notification-toast', handleToast);
    return () => window.removeEventListener('zibonbaba-notification-toast', handleToast);
  }, []);

  // Premium App Splash Screen
  if (!isMounted) {
    return (
      <div className="fixed inset-0 z-[9999] bg-neutral-dark flex flex-col items-center justify-center text-white">
        <div className="flex flex-col items-center gap-4">
          <div className="w-16 h-16 rounded-xl bg-primary flex items-center justify-center font-black text-neutral-dark text-4xl shadow-glow animate-pulse-glow">
            Z
          </div>
          <div className="text-center space-y-1">
            <h1 className="text-2xl font-black tracking-tight">
              Zibon<span className="text-primary-accent">baba</span>
            </h1>
          </div>
        </div>
        <div className="absolute bottom-16 w-36 bg-neutral-body/30 h-1 rounded-full overflow-hidden">
          <div className="bg-primary h-full rounded-full w-20 animate-pulse"></div>
        </div>
      </div>
    );
  }

  return (
    <>
      <CommandPalette />
      {/* Real-time floating Notification Toast */}
      {toast && (
        <div className="fixed bottom-20 md:bottom-8 right-6 z-[99999] max-w-sm w-full bg-slate-900 border border-white/10 rounded-2xl p-4 shadow-2xl text-white flex gap-3 items-start animate-slide-up backdrop-blur-xl">
          <div className="w-9 h-9 rounded-xl bg-amber-500/10 border border-amber-500/20 text-amber-500 flex items-center justify-center shrink-0">
            <Bell className="w-4.5 h-4.5" />
          </div>
          <div className="flex-grow min-w-0 text-left">
            <span className="text-[8px] font-black text-amber-500 uppercase tracking-widest block">{toast.module}</span>
            <h4 className="text-xs font-black truncate mt-0.5">{toast.title}</h4>
            <p className="text-[10px] text-slate-400 mt-1 leading-snug">{toast.body}</p>
          </div>
          <button onClick={() => setToast(null)} className="text-slate-500 hover:text-white shrink-0">
            <X className="w-3.5 h-3.5" />
          </button>
        </div>
      )}

      {/* Hide website storefront header & footer on admin, seller, staff, and management dashboards */}
      {hideStorefront ? (
        <div className="flex flex-col min-h-screen bg-slate-950 text-slate-100 overflow-x-hidden">
          <PWARegister />
          <main className="flex-grow flex flex-col w-full relative">
            {children}
          </main>
        </div>
      ) : isMobile ? (
        <div className="flex flex-col min-h-screen bg-neutral-light text-neutral-dark overflow-x-hidden pb-16">
          <PWARegister />
          <MobileHeader />
          <main className="flex-grow flex flex-col w-full relative">
            {children}
          </main>
          <Footer />
          <MobileBottomNavigation />
        </div>
      ) : (
        <div className="flex flex-col min-h-screen bg-neutral-light">
          <Navbar />
          <main className="flex-grow flex flex-col w-full">
            {children}
          </main>
          <Footer />
        </div>
      )}
    </>
  );
}

'use client';

import React from 'react';
import { useStore } from '../store/useStore';
import { Home, Grid, ShoppingCart, Package, User } from 'lucide-react';
import { usePathname, useRouter } from 'next/navigation';

export default function MobileBottomNavigation() {
  const { mobileTab, setMobileTab, cart, orders, language } = useStore();
  const pathname = usePathname();
  const router = useRouter();

  const cartCount = cart.reduce((acc, item) => acc + item.quantity, 0);
  const activeOrdersCount = orders.filter(o => o.status !== 'DELIVERED' && o.status !== 'CANCELLED').length;

  interface TabItem {
    id: 'home' | 'categories' | 'cart' | 'orders' | 'account';
    labelEn: string;
    labelBn: string;
    icon: React.ElementType;
    badge?: number;
    badgeColor?: string;
  }

  const tabs: TabItem[] = [
    { id: 'home', labelEn: 'Home', labelBn: 'হোম', icon: Home },
    { id: 'categories', labelEn: 'Categories', labelBn: 'ক্যাটাগরি', icon: Grid },
    { id: 'cart', labelEn: 'Cart', labelBn: 'কার্ট', icon: ShoppingCart, badge: cartCount, badgeColor: 'bg-primary-accent text-neutral-dark' },
    { id: 'orders', labelEn: 'Orders', labelBn: 'অর্ডার', icon: Package, badge: activeOrdersCount, badgeColor: 'bg-error text-white' },
    { id: 'account', labelEn: 'Account', labelBn: 'অ্যাকাউন্ট', icon: User }
  ];

  const handleTabClick = (tabId: 'home' | 'categories' | 'cart' | 'orders' | 'account') => {
    setMobileTab(tabId);
    if (pathname !== '/') {
      router.push('/');
    }
  };

  const getIsActive = (tabId: string) => {
    if (pathname === '/') {
      return mobileTab === tabId;
    }
    if (tabId === 'cart' && pathname === '/cart') return true;
    if (tabId === 'account' && (pathname === '/customer' || pathname === '/login' || pathname === '/register' || pathname === '/account')) return true;
    if (tabId === 'orders' && pathname === '/tracking') return true;
    return false;
  };

  return (
    <nav className="fixed bottom-0 left-0 right-0 z-40 bg-white/95 backdrop-blur-md border-t border-neutral-light/70 h-16 flex items-center justify-around px-2 shadow-megamenu pb-safe md:hidden">
      {tabs.map((tab) => {
        const Icon = tab.icon;
        const isActive = getIsActive(tab.id);

        return (
          <button
            key={tab.id}
            type="button"
            onClick={() => handleTabClick(tab.id)}
            className="flex flex-col items-center justify-center w-14 h-full relative cursor-pointer select-none active:scale-95 transition-transform"
          >
            {/* Icon Wrapper */}
            <div className={`p-1 rounded-full transition-all duration-200 ${isActive ? 'text-primary-dark scale-110' : 'text-neutral-muted hover:text-neutral-dark'}`}>
              <Icon className="w-5 h-5" />
            </div>

            {/* Label */}
            <span className={`text-[9px] mt-0.5 font-bold transition-colors ${isActive ? 'text-primary-dark' : 'text-neutral-muted'}`}>
              {language === 'bn' ? tab.labelBn : tab.labelEn}
            </span>

            {/* Badges */}
            {tab.badge && tab.badge > 0 ? (
              <span className={`absolute top-1.5 right-2 text-[8px] font-extrabold w-4 h-4 rounded-full flex items-center justify-center border border-white ${tab.badgeColor}`}>
                {tab.badge}
              </span>
            ) : null}

            {/* Active Indicator Bar */}
            {isActive && (
              <span className="absolute bottom-1 w-5 h-0.75 bg-primary-dark rounded-full"></span>
            )}
          </button>
        );
      })}
    </nav>
  );
}
